//
// It is not selection.go, on purpose. That file translates each borrower's
// request into its own vocabulary, because what the explorer borrows is two
// different views answering two different questions. Here the question is
// always "which path", so one message pair serves every borrower and Tag says
// which field it was for. The return slot is its own for the same reason the
// pair is: the templates view can itself be lent to the explorer, and a picker
// opened from its form must not overwrite where that borrow returns to.

// handlePickRequest lends a picker, remembering who asked.
func (a *App) handlePickRequest(msg filebrowser.PickRequestMsg) (tea.Model, tea.Cmd) {
	a.pickerReturnView = a.currentView
	log.Printf("Path picker requested by %s (tag %q)", a.currentView, msg.Tag)
	picker := filebrowser.NewPicker(a.config, msg)
	a.views[command.ViewFiles] = picker
	a.currentView = command.ViewFiles
	return a, tea.Batch(picker.Init(), a.requestResize())
}

// handlePickAnswer returns to the borrower with its answer — chosen or not —
// and drops the lent picker, so `:files` next time is the browser, not it.
func (a *App) handlePickAnswer(msg tea.Msg) (tea.Model, tea.Cmd) {
	delete(a.views, command.ViewFiles)
	a.currentView = a.pickerReturnView
	a.pickerReturnView = ""
	return a, a.returnToOrigin(msg)
//
// It mirrors handleViewerOpenRequest: the producer names only what it knows
// (the target, and whether the port is certain enough to run immediately),
// the router builds the view and remembers where esc should return to.
func (a *App) handleNetdiagOpenRequest(msg netdiag.OpenRequestMsg) (tea.Model, tea.Cmd) {
	view := netdiag.NewWithTarget(a.config, msg.Target)
	view.OriginView = a.currentView

	a.views[command.ViewNetdiag] = view
	a.currentView = command.ViewNetdiag

	cmds := []tea.Cmd{view.Init(), a.requestResize()}
	if msg.AutoRun {
		var cmd tea.Cmd
		_, cmd = view.StartRun()
		cmds = append(cmds, cmd)
	}
	return a, tea.Batch(cmds...)
}
// message carries a source, the viewer loads it in its own Init, and one place
// therefore decides what is too large or not text — and reports it.
func (a *App) handleViewerOpenRequest(msg uiviewer.OpenRequestMsg) (tea.Model, tea.Cmd) {
	if msg.Source == nil {
		return a, nil
	}

	view := uiviewer.NewWithSource(a.config, msg.Source)
	// Where esc goes back to is read from the router rather than carried on the
	// message: the view the user is looking at *is* the one that asked, and a
	// producer naming itself would be a second copy of that fact.
	view.OriginView = a.currentView

	a.views[command.ViewViewer] = view
	a.currentView = command.ViewViewer
	return a, tea.Batch(view.Init(), a.requestResize())
}
// handleExplorerCloneRequest borrows the workspaces view to pick a clone target.
func (a *App) handleExplorerCloneRequest() (tea.Model, tea.Cmd) {
	a.selectionReturnView = a.currentView
	log.Printf("Explorer clone request: switching to workspaces for directory selection")
	return a, a.openBrowser(
		command.ViewWorkspaces,
		workspaces.NewForSelection(a.config, cloneDestinationPrompt),
	)
}

// openBrowser installs a view built in selection mode and lays it out.
func (a *App) openBrowser(view command.ViewType, model tea.Model) tea.Cmd {
	a.views[view] = model
	a.selectionLent = view
	a.currentView = view
	return tea.Batch(model.Init(), a.requestResize())
}

// handleDirectorySelected returns to the explorer with the chosen path.
func (a *App) handleDirectorySelected(msg workspaces.DirectorySelectedMsg) (tea.Model, tea.Cmd) {
	log.Printf("Directory selected: %s, returning to %s", msg.Path, a.selectionReturnView)
	)
}

// rescanInOrigin hands a scan request to the list the target belongs to, and
// stays there. The view is created if it is not open — the request can arrive
// from a cached row whose list was dropped on a context switch.
func (a *App) rescanInOrigin(view command.ViewType, request tea.Msg) (tea.Model, tea.Cmd) {
	a.createView(view)
	held, ok := a.views[view]
	if !ok {
		return a, nil
	}
	a.currentView = view
	updatedView, cmd := held.Update(request)
	a.views[view] = updatedView
	return a, tea.Batch(cmd, a.requestResize())
}

// openSecurityView installs a freshly built security view, records where esc
// should return to, and lays it out.
func (a *App) openSecurityView(view security.Model, origin command.ViewType) tea.Cmd {
	view.OriginView = origin
	a.views[command.ViewSecurity] = view
	a.currentView = command.ViewSecurity
	return tea.Batch(view.Init(), a.requestResize())
}

