func (a *App) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		a.resize(msg.Width, msg.Height)
		return a, nil

	case tea.KeyMsg:
		return a.handleKeyMsg(msg)

	// ── Contexts and themes ──────────────────────────────────────────────
	case configuration.ConfigSavedMsg:
		return a.handleConfigSaved(msg)

	case MCPServerStartedMsg:
		return a.handleMCPServerStarted(msg)

	case mcpJobsRequestMsg:
		return a.handleMCPJobsRequest(msg)

	case mcpForwardsRequestMsg:
		return a.handleMCPForwardsRequest(msg)

	case mcpStartRequestMsg:
		return a.handleMCPStartRequest(msg)

	case mcpCancelRequestMsg:
		return a.handleMCPCancelRequest(msg)

	case jobs.RefusedMsg:
		return a.handleMCPRefused(msg)

	case ContextSwitchCompleteMsg:
		return a.handleContextSwitchComplete(msg)

	case ContextSwitchErrorMsg:
		log.Printf("ERROR: Context operation failed: %v", msg.Error)
		a.switchingTo = ""
		return a, nil

	case ContextListMsg:
		return a.handleContextList(msg)

	// ── GitLab authentication ────────────────────────────────────────────
	case auth.AuthResultMsg:
		return a.handleAuthResult(msg)

	case auth.LogoutCompleteMsg:
		return a.handleLogoutComplete(msg)

	case ForgeAutoLoginMsg:
		return a.handleAutoLoginResult(msg)

	// ── Long-running work ────────────────────────────────────────────────
	// The shared spinner frame. One chain for the whole application, held by
	// the router (D5) — see jobs.go.
	case jobTickMsg:
		return a.handleJobTick(msg)

	// ── The scanners' detection (§3.86) — see scan_tools.go ─────────────
	case scanToolsDetectedMsg:
		return a.handleScanToolsDetected(msg)

	case shared.ScanToolsDetectRequestMsg:
		return a, a.detectScanTools()

	// ── The forge index — see forge_index.go ────────────────────────────
	case forgeIndexLoadedMsg:
		return a.handleForgeIndexLoaded(msg)

	case forgeIndexStartedMsg:
		return a.handleForgeIndexStarted(msg)

	case forgeIndexBuiltMsg:
		return a.handleForgeIndexBuilt(msg)

	case shared.ForgeIndexEditMsg:
		return a.handleForgeIndexEdit(msg)

	case shared.ForgeIndexRefreshMsg:
		return a.handleForgeIndexRefresh()

	// Every message below reports on work already under way, and each is routed
	// to the view that started it rather than to the one on screen. None of
	// them changes the current view: a scan can run for minutes, and dragging
	// the user back to watch it was the whole of D67.
	// ── Port forwards (§3.1) ─────────────────────────────────────────────
	// The registry is the router's; a view asks and is told. Opening does
	// I/O, so it is answered with a Cmd rather than handled here.
	case forward.OpenMsg:
		return a.handleForwardOpen(msg)

	case forward.OpenedMsg:
		return a.handleForwardOpened(msg)

	case forward.CloseMsg:
		return a.handleForwardClose(msg)

	case forward.ToggleMsg:
		return a.handleForwardToggle(msg)

	case forward.ProxyPortSetMsg:
		return a.handleProxyPortSet(msg)

	case forward.ToggledMsg:
		return a.handleForwardToggled(msg)

	case forward.RestoredMsg:
		return a.handleForwardRestored(msg)

	case forward.SavedMsg:
		return a.handleForwardSaved(msg)

	case forward.RefreshMsg:
		return a.handleForwardRefresh()

	case jobs.StartMsg:
		return a.handleStartJobs(msg)

	case jobs.CancelOpenMsg:
		return a.handleCancelOpen(msg)

	case jobs.CancelMsg:
		return a.handleCancel(msg)

	case jobs.CancelItemMsg:
		return a.handleCancelItem(msg)

