package agentusageview

import "testing"

// ctrl+r starts a full read (nothing in flight); the view is left before it
// answers; coming back must still deliver the full read the user asked for.
func TestReviewCtrlRFullReadInFlightThenLeave(t *testing.T) {
	m, _ := atFixture(t)
	m, _ = opened(t, m, "ctrl+r")
	if !m.reading || m.fullPending || !m.agentsLoading {
		t.Fatalf("precondition: full read in flight, reading=%t pending=%t loading=%t", m.reading, m.fullPending, m.agentsLoading)
	}
	m, _, _ = leave(t, m)
	m, cmd := resumed(t, m)
	reads := usageMsgs(batchMsgs(t, cmd))
	if len(reads) != 1 || !reads[0].delta.Full() {
		t.Errorf("the refresh pressed before leaving is lost: full=%v", len(reads) == 1 && reads[0].delta.Full())
	}
}

// Open, leave before the first answer, resume: the first read is full (fresh
// cursor) but no spinner says the table is loading.
func TestReviewOpenLeaveResumeSpinner(t *testing.T) {
	m, _, _ := openedFixture(t)
	m, _, _ = leave(t, m)
	m, cmd := resumed(t, m)
	reads := usageMsgs(batchMsgs(t, cmd))
	t.Logf("full=%v agentsLoading=%v rows=%d", len(reads) == 1 && reads[0].delta.Full(), m.agentsLoading, len(m.agentTable.Visible()))
}
EOF
go test ./internal/ui/agentusageview/ -run Review -v -count=1 2>&1 | tail -15

